library(httr2)

# Set up base request with API key
gas_request &lt;- request("https://api.collectapi.com/gasPrice") |&gt;
  req_headers("X-API-KEY" = "apikey 4mEsIM76saqF28IR638bWr:6XJHqxtklK7pw7haSU8wy9")

# Get gas prices for a specific country
get_gas_prices &lt;- function(country = "united-states") {
  gas_request |&gt;
    req_url_path_append("fromCity") |&gt;
    req_url_query(country = country) |&gt;
    req_perform() |&gt;
    resp_body_json()
}

# Get all available countries
get_countries &lt;- function() {
  gas_request |&gt;
    req_url_path_append("countries") |&gt;
    req_perform() |&gt;
    resp_body_json()
}

# Usage examples
countries &lt;- get_countries()
us_prices &lt;- get_gas_prices("united-states")
uk_prices &lt;- get_gas_prices("united-kingdom")
Replace "YOUR_API_KEY_HERE" with your actual CollectAPI key from their dashboard.
